108	    /**
109	     * Run the simulation from its current state for a single step.
110	     * Iterate over the whole field updating the state of each
111	     * actor in the field. One  day lasts 4 steps, with day and night alternating every 2 steps.
112	     * Buttons are disabled before the simulation starts and enabled after the simulation is finsihed.
113	     */
114	    public void simulateOneStep()
115	    {
116	        view.disableButton();
117	        step++;
118	        if(step % 2 == 0){
119	            isDay  = !isDay;
120	            if(isDay){
121	                numberOfDays++;
122	            }
123	        }
124	
125	        // Provide space for newborn actors.
126	        List<Actor> newAnimals = new ArrayList<>();  
127	        List<Actor> newGrass = new ArrayList<>();  
128	
129	        getRandomWeather();
130	        while(!isDay && weather == weather.SUNNY){
131	            getRandomWeather();
132	        }
133	        // Let all actors act.
134	        //iterates through all the animals and hunters
135	
136	        for(Iterator<Actor> it = animals.iterator(); it.hasNext(); ) {
137	            Actor animal = it.next();
138	            animal.act(newAnimals,this);
139	            if(! animal.isActive()) {
140	                it.remove();
141	            }
142	        }
143	        animals.addAll(newAnimals);
144	        noOfGrass = 0;
145	        for(Iterator<Actor> it = plants.iterator(); it.hasNext(); ) {
146	            Actor plants = it.next();
147	            plants.act(newGrass,this);
148	            if(! plants.isActive()) {
149	                it.remove();
150	            }else if(plants instanceof Plants){
151	                noOfGrass++;
152	            }
153	        }
154	        plants.addAll(newGrass);
155	
156	        if(step % 500 == 0){
157	            introduceInfection();
158	        }
159	
160	        view.showStatus(field);
161	        view.enableButton();
162	    }
